export type RichTextEditorProps = {
	/** Stable caller-owned record identity. Change to discard selection/history, even for equal JSON. */
	documentKey: string;
	value: RichTextDocument;
	onChange: (value: RichTextDocument) => void;
	label: string;
	readOnly?: boolean;
};
function renderNode(node: RichTextNode, key: number): ReactNode {
	if (node.type === "text") {
		let text: ReactNode = node.text;
		for (const mark of node.marks ?? [])
			text =
				mark.type === "link" ? (
					<a href={mark.attrs.href} rel="noopener noreferrer nofollow">
						{text}
					</a>
				) : (
					createElement(
						(
							{
								bold: "strong",
								italic: "em",
								strike: "s",
								code: "code",
							} as const
						)[mark.type],
						null,
						text,
					)
				);
		return <span key={key}>{text}</span>;
	}
	const children = node.content?.map(renderNode);
	if (node.type === "doc") return <div key={key}>{children}</div>;
	if (node.type === "codeBlock")
		return (
			<pre key={key}>
				<code>{children}</code>
			</pre>
		);
	const tag =
		node.type === "heading"
			? `h${node.attrs?.level}`
			: (
					{
						paragraph: "p",
						blockquote: "blockquote",
						bulletList: "ul",
						orderedList: "ol",
						listItem: "li",
						hardBreak: "br",
					} as Record<string, string>
				)[node.type];
	return createElement(
		tag,
		{
			key,
			...(node.type === "orderedList" ? { start: node.attrs?.start } : {}),
		},
		children,
	);
}
