		<Client key={props.documentKey} {...props} value={value} />
	) : (
		<div aria-busy={!failed}>
			<RichTextContent value={value} label={props.label} />
			<output>{failed ? "Editor could not load." : "Loading editor…"}</output>
		</div>
	);
}

