		typeof value !== "string" ||
		value.length > 2048 ||
		hasInvalidRichTextScalar(value) ||
		/\s/u.test(value) ||
		[...value].some(
			(character) =>
				character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127,
		)
	)
		return false;
	try {
		const url = new URL(value);
		return (
			["https:", "http:", "mailto:"].includes(url.protocol) &&
			!url.username &&
			!url.password &&
